delete from formato_oficial_campo
 where formato_id = (
   select id from formato_oficial
    where codigo_anexo = '1' and version = 'dof-2026-09-24'
 );

insert into formato_oficial_campo (
  formato_id, orden, numero, padre, nombre, etiqueta_xml,
  obligatoriedad, tipo_dato, longitud, formato, pagina_dof
)
select f.id, v.orden, v.numero, v.padre, v.nombre, v.etiqueta_xml,
       v.obligatoriedad, v.tipo_dato, v.longitud, v.formato, v.pagina_dof
from formato_oficial f
cross join (values
    (1, 'A', null, 'Archivo XML', '<archivo>', 'Obligatorio', 'Etiqueta', 'N/A', 'N/A', 4),
    (2, 'AA', null, 'Informe', '<informe>', 'Obligatorio', 'Etiqueta', 'N/A', 'N/A', 4),
    (3, '1', null, 'Mes reportado', '<mes_reportado>', 'Obligatorio', 'Numérico', '6', 'AAAAMM', 4),
    (4, '2', null, 'Datos de identificación de quien realiza la Actividad Vulnerable', '<sujeto_obligado>', 'Obligatorio', 'Etiqueta', 'N/A', 'N/A', 4),
    (5, '2.1', '2', 'Clave de la Entidad Colegiada por medio de la cual se remiten los avisos', '<clave_entidad_colegiada>', 'Obligatorio', 'Alfanumérico', '12', 'Patrón: LLLAAMMDDXXX; en donde, L=(A- Z) letra o caracteres & o Ñ, AA=año, MM=mes, DD=día, X=alfanumérico', 4),
    (6, '2.2', '2', 'Clave de quien realiza la Actividad Vulnerable que genera el aviso', '<clave_sujeto_obligado>', 'Obligatorio', 'Alfanumérico', '12-13', 'Patrón: LLLLAAMMDDXXX/LLLAAMMDDXXX; en donde, L=(A-Z) letra o caracteres &o Ñ, AA=año, MM=mes, DD=día, X=alfanumérico', 4),
    (7, '2.3', '2', 'Clave de la actividad vulnerable', '<clave_actividad>', 'Obligatorio', 'Alfanumérico', '3', 'Patrón: AAA', 4),
    (8, '3', null, 'Datos del Aviso', '<aviso>', 'Obligatorio', 'Etiqueta', 'N/A', 'N/A', 4),
    (9, '3.1', '3', 'Referencia del Aviso', '<referencia_aviso>', 'Obligatorio', 'Alfanumérico', '1 -14', '', 4),
    (10, '3.2', '3', 'Datos si el aviso es modificatorio', '<modificatorio>', 'Obligatorio', 'Etiqueta', 'N/A', 'N/A', 4),
    (11, '3.2.1', '3.2', 'Folio del Aviso previo que se modifica', '<folio_modificacion>', 'Obligatorio', 'Alfanumérico', '6 - 14', 'Patrón: AAAA-999999999 (sin ceros a la izquierda)', 4),
    (12, '3.2.2', '3.2', 'Descripción de la modificación', '<descripcion_modificacion>', 'Obligatorio', 'Alfanumérico', '1-3000', '', 4),
    (13, '3.3', '3', 'Prioridad de aviso', '<prioridad>', 'Obligatorio', 'Numérico', '1', 'Patrón: 9', 4),
    (14, '3.4', '3', 'Alertas', '<alerta>', 'Obligatorio', 'Etiqueta', 'N/A', 'N/A', 4),
